Object.assign(window.TEM8_DICTIONARY, {"daffodil":{"oxford":{"phon":"ˈdæfədɪl","pos":"noun","senses":[{"en":"a tall yellow spring flower that is like a trumpet in shape. It is a national symbol of Wales.","cn":"黄水仙（威尔士的民族象征）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黄水仙（花）","en":"A daffodil is a yellow spring flower with a central part shaped like a tube and a long stem."}]},"media":{"img":["media/pic/flowerlabels_flowers_comp.jpg","media/thumb/daffodil.jpg"],"uk":"media/uk/daffodil__gb_1.mp3","us":"media/us/daffodil__us_1.mp3"}},"dark":{"media":{"uk":"media/uk/dark__gb_1.mp3","us":"media/us/dark__us_1.mp3"},"oxford":{"phon":"dɑːk","pos":"adjective","senses":[{"en":"with no or very little light, especially because it is night","cn":"黑暗的；昏暗的；阴暗的","sc":"with little light","ex":{"en":"a dark room/street/forest/night","cn":"黑暗的房间；昏暗的街道；黑黝黝的森林；漆黑的夜晚"}},{"en":"not light; closer in shade to black than to white","cn":"深色的；暗色的","sc":"colours","ex":{"en":"dark blue/green/red/brown","cn":"深蓝色；墨绿色；深红色；深棕色"}},{"en":"having a colour that is close to black","cn":"近乎黑色的","sc":"colours","ex":{"en":"He wore a dark suit and a plain tie.","cn":"他穿着深色西装，打着素色领带。"}},{"en":"brown or black in colour","cn":"褐色的；黝黑的；乌黑的","sc":"hair/skin/eyes","ex":{"en":"Sue has long dark hair.","cn":"休留着长长的黑发。"}},{"en":"having dark hair, eyes, etc.","cn":"有深色头发（或眼睛等）的","sc":"hair/skin/eyes","ex":{"en":"a dark handsome stranger","cn":"一位黑头发的英俊陌生人"}},{"en":"mysterious; hidden and not known about","cn":"神秘的；隐秘的；隐藏的","sc":"mysterious","ex":{"en":"There are no dark secrets in our family.","cn":"我们家没有不为人知的秘密。"}},{"en":"evil or frightening","cn":"邪恶的；阴险的；凶恶的","sc":"evil","ex":{"en":"There was a darker side to his nature.","cn":"他本性中有阴险的一面。"}},{"en":"unpleasant and without any hope that something good will happen","cn":"忧郁的；不快的；无望的","sc":"without hope","ex":{"en":"the darkest days of Fascism","cn":"法西斯统治下最黑暗的日子"}},{"en":"produced with the back part of the tongue close to the back of the mouth. In many accents of (= ways of pronouncing) English, dark /l/ is used after a vowel, as in ball.","cn":"模糊的","sc":"phonetics"},{"en":"the lack of light in a place, especially because it is night","cn":"黑暗；暗处","g":"[singular]","sc":"no light","ex":{"en":"Are the children afraid of the dark?","cn":"孩子们怕黑吗？"},"pos":"noun"},{"en":"an amount of something that is dark in colour","cn":"暗色；阴影","g":"[uncountable]","sc":"colour","ex":{"en":"patterns of light and dark","cn":"明暗相间的图案"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"黑暗的;昏暗的;天黑的","en":"When it is dark, there is not enough light to see properly, for example because it is night.","ex":{"en":"When she awoke it was evening and already dark","cn":"她醒来时已是晚上，天已经黑了。"}},{"pos":"N-SING 单数名词","cn":"黑暗;昏暗;暗处","en":"The dark is the lack of light in a place.","ex":{"en":"Her mother was sitting in the dark by the stove in her rocking chair","cn":"她母亲坐在炉边暗处的摇椅里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"黑色的;深色的;暗色的","en":"If you describe something as dark, you mean that it is black in colour, or a shade that is close to black.","ex":{"en":"He wore a dark suit and carried a black attaché case","cn":"他身穿暗色西服，手提黑色公文包。"}},{"pos":"COMB in COLOUR 与颜色词构成的词","cn":"(颜色)深的，暗的","en":"When you use dark to describe a colour, you are referring to a shade of that colour which is close to black, or seems to have some black in it.","ex":{"en":"She was wearing a dark blue dress.","cn":"她穿着一件深蓝色的礼服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发、眼睛或肤色)棕色的，黑色的","en":"If someone has dark hair, eyes, or skin, they have brown or black hair, eyes, or skin.","ex":{"en":"He had dark, curly hair","cn":"他有一头卷曲的黑发。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(白人）有着棕色（或黑色）头发（且皮肤略带棕色）的，肤色深的","en":"If you describe a white person as dark, you mean that they have brown or black hair, and often a brownish skin.","ex":{"en":"Carol is a tall, dark, Latin type of woman","cn":"卡萝尔身材高大，黑发棕肤，是个有着拉丁风情的女子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(时期）黑暗的，恐怖的，悲惨的","en":"A dark period of time is unpleasant or frightening.","ex":{"en":"Once again there's talk of very dark days ahead","cn":"又有传言说以后的日子会非常艰难。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方)神秘的，隐秘的","en":"A dark place or area is mysterious and not fully known about.","ex":{"en":"The spacecraft is set to throw new light on to a dark corner of the solar system.","cn":"这艘宇宙飞船可能会让人们对太阳系中的一个神秘角落有更新的认识。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(想法）忧郁的，悲观的","en":"Dark thoughts are sad, and show that you are expecting something unpleasant to happen.","ex":{"en":"Troy's chatter kept me from thinking dark thoughts.","cn":"特洛伊的喋喋不休让我暂时收起了阴郁思绪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(眼神或话语）阴险的，邪恶的，不祥的","en":"Dark looks or remarks make you think that the person giving them wants to harm you or that something horrible is going to happen.","ex":{"en":"Garin shot him a dark glance, as if in warning.","cn":"加林恶狠狠地瞪了他一眼，似乎是在警告。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（指与严肃或令人不快的事物相关的)黑色的","en":"If you describe something as dark, you mean that it is related to things that are serious or unpleasant, rather than light-hearted.","ex":{"en":"Their dark humor never failed to astound him","cn":"他们的黑色幽默总能让他咋舌。"}},{"pos":"PHRASE 短语","cn":"天黑后","en":"If you do something after dark, you do it when the sun has set and night has begun.","ex":{"en":"They avoid going out alone after dark.","cn":"他们避免在天黑以后独自外出。"}},{"pos":"PHRASE 短语","cn":"天黑前","en":"If you do something before dark, you do it before the sun sets and night begins.","ex":{"en":"They'll be back well before dark.","cn":"他们会在天黑前早早返回。"}},{"pos":"PHRASE 短语","cn":"（对…）一无所知，毫不知情","en":"If you are in the dark about something, you do not know anything about it.","ex":{"en":"The investigators admit that they are completely in the dark about the killing","cn":"调查人员承认他们对这起谋杀一无所知。"}},{"pos":"PHRASE 短语","cn":"瞎猜;盲干","en":"If you describe something someone says or does as a shot in the dark or a stab in the dark, you mean they are guessing that what they say is correct or that what they do will be successful.","ex":{"en":"Every single one of those inspired guesses had been shots in the dark.","cn":"所有那些凭直觉的猜测都是无根据的瞎猜。"}},{"pos":"","cn":"","en":"leap in the dark→see: ;"}]},"examples":[{"en":"The dark clouds in the sky meant that a storm was coming.","cn":"天空中的乌云预示暴风雨即将来临。"},{"en":"The figure he came up with was really just a shot in the dark.","cn":"他得出的数字实际上只是瞎猜而已。"}]},"dance":{"media":{"uk":"media/uk/dance__gb_1.mp3","us":"media/us/dance__us_1.mp3"},"oxford":{"phon":"dɑːns","pos":"noun","senses":[{"en":"a series of movements and steps that are usually performed to music; a particular example of these movements and steps","cn":"舞蹈；舞步","g":"[countable]","ex":{"en":"Do you know any other Latin American dances?","cn":"你会跳其他拉美舞蹈吗？"}},{"en":"the art of dancing, especially for entertainment","cn":"舞蹈（艺术）","g":"[uncountable]","ex":{"en":"an evening of drama, music and dance","cn":"戏剧、音乐和舞蹈晚会"}},{"en":"an act of dancing","cn":"跳舞","g":"[countable]","ex":{"en":"Let's have a dance.","cn":"咱们跳个舞吧。"}},{"en":"a social event at which people dance","cn":"舞会","g":"[countable]","ex":{"en":"We hold a dance every year to raise money for charity.","cn":"我们每年举行一场舞会，为慈善事业募捐。"}},{"en":"a piece of music for dancing to","cn":"舞曲","g":"[countable]","ex":{"en":"The band finished with a few slow dances.","cn":"乐队最后演奏了几首节奏缓慢的舞曲。"}},{"en":"to move your body to the sound and rhythm of music","cn":"跳舞","g":"[intransitive]","ex":{"en":"Do you want to dance?","cn":"你想跳舞吗？"},"pos":"verb"},{"en":"to do a particular type of dance","cn":"跳…舞","g":"[transitive]","ex":{"en":"to dance the tango","cn":"跳探戈舞"},"pos":"verb"},{"en":"to move in a lively way","cn":"跳跃；雀跃；轻快地移动","g":"[intransitive]","ex":{"en":"The children danced around her.","cn":"孩子们在她周围蹦蹦跳跳。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跳舞","en":"When you dance, you move your body and feet in a way which follows a rhythm, usually in time to music.","ex":{"en":"Polly had never learned to dance","cn":"波莉从未学过跳舞。"}},{"pos":"N-COUNT 可数名词","cn":"舞蹈;舞步","en":"A dance is a particular series of graceful movements of your body and feet, which you usually do in time to music.","ex":{"en":"Sometimes the people doing this dance hold brightly colored scarves","cn":"有时跳这种舞的人会手拿色彩鲜艳的丝巾。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）跳舞;共舞","en":"When you dance with someone, the two of you take part in a dance together, as partners. You can also say that two people dance.","ex":{"en":"It's a terrible thing when nobody wants to dance with you","cn":"没有人想和你跳舞是一件很糟糕的事情。"}},{"pos":"N-COUNT 可数名词","cn":"舞会","en":"A dance is a social event where people dance with each other.","ex":{"en":"She often went to parties and dances at Littlecote","cn":"她经常去利特尔科特参加聚会和舞会。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"舞蹈演出;舞蹈艺术","en":"Dance is the activity of performing dances, as a public entertainment or an art form.","ex":{"en":"She loves dance, drama and music","cn":"她喜欢舞蹈、戏剧和音乐。"}},{"pos":"VERB 动词","cn":"跳（舞);表演（舞蹈）","en":"If you dance a particular kind of dance, you do it or perform it.","ex":{"en":"Then we put the music on, and we all danced the Charleston","cn":"接着我们打开音乐，一起跳起查尔斯顿舞来。"}},{"pos":"VERB 动词","cn":"跳跃;雀跃;轻快地移动","en":"If you dance somewhere, you move there lightly and quickly, usually because you are happy or excited.","ex":{"en":"He danced off down the road","cn":"他蹦蹦跳跳地沿着马路走了。"}},{"pos":"VERB 动词","cn":"跳动;晃动","en":"If you say that something dances, you mean that it moves about, or seems to move about, lightly and quickly.","ex":{"en":"Light danced on the surface of the water","cn":"灯光在水面上摇曳。"}},{"pos":"PHRASE 短语","cn":"使…疲于奔波;使…白忙一场;给…造成许多麻烦","en":"If someone leads you a merry dance, they make you do things over a long period of time which cause you problems and do not benefit you in any way."},{"pos":"","cn":"","en":"to dance to someone'stune→see: ; to make a song and dance about→see: ;"}]},"examples":[{"en":"We hold a dance every year to raise money for charity.","cn":"我们每年举行一场舞会，为慈善事业募捐。"},{"en":"The sun shone on the sea and the waves danced and sparkled.","cn":"太阳照在海面上，碧浪翻滚，波光粼粼。"}]},"daunting":{"media":{"uk":"media/uk/daunting__gb_1.mp3","us":"media/us/daunting__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人畏惧的;令人胆怯的;让人气馁的","en":"Something that is daunting makes you feel slightly afraid or worried about dealing with it.","ex":{"en":"They were faced with the daunting task of restoring the house","cn":"他们面临着修复房子的艰巨任务。"}}]},"examples":[{"en":"She has the daunting task of cooking for 20 people every day.","cn":"她每天得做 20 个人的饭，这是一项可怕的任务。"},{"en":"Starting a new job can be a daunting prospect.","cn":"开始一项新工作有时会让人望而却步。"}],"oxford":{"phon":"ˈdɔːntɪŋ","pos":"adjective","senses":[{"en":"making somebody feel nervous and less confident about doing something; likely to make somebody feel this way","cn":"使胆怯；使气馁；使失去信心","ex":{"en":"She has the daunting task of cooking for 20 people every day.","cn":"她承担着每天给 20 人做饭的艰巨任务。"}}]}},"damage":{"media":{"uk":"media/uk/damage__gb_1.mp3","us":"media/us/damage__us_1.mp3"},"oxford":{"phon":"ˈdæmɪdʒ","pos":"noun","senses":[{"en":"physical harm caused to something which makes it less attractive, useful or valuable","cn":"（有形的）损坏，破坏，损失","g":"[uncountable]","ex":{"en":"serious/severe damage","cn":"严重/严重损坏"}},{"en":"harmful effects on somebody/something","cn":"损害；伤害","g":"[uncountable]","ex":{"en":"The children suffered psychological and emotional damage.","cn":"孩子们遭受了心理和情感上的伤害。"}},{"en":"an amount of money that a court decides should be paid to somebody by the person, company, etc. that has caused them harm or injury","cn":"（法院判定的）损害赔偿金","g":"[plural]","ex":{"en":"He was ordered to pay damages totalling £30 000.","cn":"他被责令支付总额为 3 万英镑的损害赔偿金。"}},{"en":"to have a bad or harmful effect on something/somebody","cn":"破坏；毁坏；损害；伤害","lab":"especially British English","ex":{"en":"The church was badly damaged by the 1997 earthquake.","cn":"这座教堂在 1997 年的地震中严重受损。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"损坏;破坏;毁坏","en":"To damage an object means to break it, spoil it physically, or stop it from working properly.","ex":{"en":"He maliciously damaged a car with a baseball bat","cn":"他用棒球棒恶意损毁了一辆汽车。"}},{"pos":"VERB 动词","cn":"损害;伤害","en":"To damage something means to cause it to become less good, pleasant, or successful.","ex":{"en":"Jackson doesn't want to damage his reputation as a political personality","cn":"杰克逊不想损害自己政界名人的声誉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对物的）损坏，破坏，损失","en":"Damage is physical harm that is caused to an object.","ex":{"en":"The blast caused extensive damage to the house","cn":"爆炸给这所房子造成了大面积的损坏。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对人、情况、行为的）损害，伤害，不良影响","en":"Damage consists of the unpleasant effects that something has on a person, situation, or type of activity.","ex":{"en":"Incidents of this type cause irreparable damage to relations with the community","cn":"这类事件会对与该社群的关系造成不可弥合的伤害。"}},{"pos":"N-PLURAL 复数名词","cn":"（法院判定的）损害赔偿金","en":"If a court of law awards damages to someone, it orders money to be paid to them by a person who has damaged their reputation or property, or who has injured them.","ex":{"en":"He was vindicated in court and damages were awarded.","cn":"他在法庭上被证明无罪，并且获得了损害赔偿金。"}},{"pos":"PHRASE 短语","cn":"事已至此;已造成的损害无法挽回","en":"If you say 'the damage is done', you mean that it is too late now to prevent the harmful effects of something that has already happened.","ex":{"en":"Once the damage is done, even modern surgery can't undo it entirely.","cn":"伤害一旦造成，即使是现代外科手术也无法将其完全消除。"}}]},"examples":[{"en":"I'm going — I've done enough damage here already.","cn":"我要走了 — 我在这里造成的损害已经够大了。"},{"en":"He was ordered to pay damages totalling £30 000.","cn":"他被责令支付总额为 3 万英镑的损害赔偿金。"}]},"darkness":{"media":{"uk":"media/uk/darkness__gb_1.mp3","us":"media/us/darkness__us_1.mp3"},"oxford":{"phon":"ˈdɑːknəs","pos":"noun","senses":[{"en":"the state of being dark, without any light","cn":"黑暗；阴暗；漆黑","ex":{"en":"After a few minutes our eyes got used to the darkness.","cn":"几分钟后我们的眼睛就适应了黑暗。"}},{"en":"the quality or state of being dark in colour","cn":"墨色；暗色；深色","ex":{"en":"It depends on the darkness of your skin.","cn":"这取决于你肤色的深浅。"}},{"en":"evil","cn":"邪恶；罪恶","lab":"literary","ex":{"en":"the forces of darkness","cn":"邪恶势力"}}]},"examples":[{"en":"After a few minutes our eyes got used to the darkness.","cn":"几分钟后我们的眼睛就适应了黑暗。"},{"en":"The house was plunged into total darkness when the electricity was cut off.","cn":"停电后，整座房子陷入一片黑暗。"}]},"dazed":{"media":{"uk":"media/uk/dazed__gb_1.mp3","us":"media/us/dazed__us_1.mp3"},"oxford":{"phon":"deɪzd","pos":"adjective","senses":[{"en":"unable to think clearly, especially because of a shock or because you have been hit on the head","cn":"（由于震惊或头部受到撞击）神志不清的，茫然的","ex":{"en":"Survivors waited for the rescue boats, dazed and frightened.","cn":"生还者不知所措，心有余悸，等待着救援船只。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恍惚的;头昏的;茫然的","en":"If someone is dazed, they are confused and unable to think clearly, often because of shock or a blow to the head.","ex":{"en":"At the end of the interview I was dazed and exhausted.","cn":"面试进行到最后，我感到头昏脑胀，筋疲力尽。"}}]},"examples":[{"en":"Survivors waited for the rescue boats, dazed and frightened.","cn":"生还者不知所措，心有余悸，等待着救援船只。"},{"en":"Jimmy was still dazed by the blow to his head.","cn":"吉米由于头部被击，仍然神志不清。"}]},"danger":{"media":{"uk":"media/uk/danger__gb_1.mp3","us":"media/us/danger__us_1.mp3"},"oxford":{"phon":"ˈdeɪndʒə(r)","pos":"noun","senses":[{"en":"the possibility of something happening that will injure, harm or kill somebody, or damage or destroy something","cn":"危险；风险","g":"[uncountable]","ex":{"en":"Danger! Keep Out!","cn":"危险！请勿入内！"}},{"en":"the possibility of something bad or unpleasant happening","cn":"（坏事或不快之事发生的）可能性，危险","g":"[countable, uncountable]","ex":{"en":"There is no danger of a bush fire now.","cn":"目前没有山林大火之虞。"}},{"en":"a person or thing that may cause damage, or harm somebody","cn":"危险的人；危险因素；危害；威胁","g":"[countable]","ex":{"en":"There are many hidden dangers for small children in the home.","cn":"家里有很多对幼儿安全不利的潜在危险。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"危险","en":"Danger is the possibility that someone may be harmed or killed.","ex":{"en":"My friends endured tremendous danger in order to help me","cn":"为了帮助我，朋友们冒了极大的危险。"}},{"pos":"N-COUNT 可数名词","cn":"危险的事物（或人）；危害;威胁","en":"A danger is something or someone that can hurt or harm you.","ex":{"en":"...the dangers of smoking","cn":"吸烟的危害"}},{"pos":"N-SING 单数名词","cn":"(不愉快之事发生的)可能性，风险","en":"If there is a danger that something unpleasant will happen, it is possible that it will happen.","ex":{"en":"There is a real danger that some people will no longer be able to afford insurance","cn":"一些人很可能再也负担不起保险了。"}},{"pos":"PHRASE 短语","cn":"(病人）脱离危险","en":"If someone who has been seriously ill is out of danger, they are still ill, but they are not expected to die."}]},"examples":[{"en":"‘Nicky won't find out, will she?’ ‘Oh, no, there's no danger of that.’ “","cn":"尼基不会察觉吧，会吗？” “不会，绝对不会的。”"},{"en":"Children's lives are in danger every time they cross this road.","cn":"孩子们每次过这条马路都面临着生命危险。"}]},"damn":{"oxford":{"phon":"dæm","pos":"exclamation","senses":[{"en":"a swear word that people use to show that they are annoyed, disappointed, etc.","cn":"（表示厌烦、失望等）该死，他妈的，讨厌","ex":{"en":"Oh damn! I forgot he was coming.","cn":"真该死！我把他要来这事儿给忘了。"}},{"en":"a swear word that people use to show that they are annoyed with somebody/something","cn":"（表示厌烦）可恶的，该死的，讨厌的","ex":{"en":"Where's that damn book!","cn":"那该死的书在哪儿呢！"},"pos":"adjective"},{"en":"a swear word that people use to emphasize what they are saying","cn":"（加强语气）十足的，完全的","ex":{"en":"What a damn shame!","cn":"真是太遗憾了！"},"pos":"adjective"},{"en":"used when swearing at somebody/something to show that you are angry","cn":"（表示愤怒）该死，混账","lab":"informal","ex":{"en":"Damn you! I'm not going to let you bully me.","cn":"你这个浑蛋！甭想欺负我。"},"pos":"verb"},{"en":"to decide that somebody must suffer in hell","cn":"令（某人）下地狱","pos":"verb"},{"en":"to criticize somebody/something very strongly","cn":"猛烈抨击","ex":{"en":"The film was damned by the critics for its mindless violence.","cn":"这部影片因无谓的暴力受到评论家的强烈谴责。"},"pos":"verb"},{"en":"a swear word that people use to show that they are annoyed with somebody/something","cn":"（表示厌烦）可恶的，该死的，讨厌的","ex":{"en":"Don't be so damn silly!","cn":"别那么傻了！"},"pos":"adverb"},{"en":"a swear word that people use to emphasize what they are saying","cn":"（加强语气）十足的，完全的","ex":{"en":"damn good","cn":"好得不得了"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"(表示愤怒或不耐烦)该死，可恶，他妈的","en":"Damn ,damn it, and dammit are used by some people to express anger or impatience.","ex":{"en":"Don't be flippant, damn it! This is serious.","cn":"别不当回事，该死！这可不是闹着玩儿的事。"}},{"pos":"ADJ 形容词","cn":"(用于加强语气)该死的，可恶的，十足的，完全的","en":"Damn is used by some people to emphasize what they are saying.","ex":{"en":"There's not a damn thing you can do about it now.","cn":"现在你对此做什么都完全无济于事。"}},{"pos":"VERB 动词","cn":"谴责，指责(政策、行动等)","en":"If you say that a person or a news report damns something such as a policy or action, you mean that they are very critical of it.","ex":{"en":"...a sensational book in which she damns the ultra-right party.","cn":"她在其中大力鞭挞该极右党派的耸人听闻的书"}},{"pos":"PHRASE 短语","cn":"毫不在乎;完全不关心","en":"If you say that someone does not give a damn about something, you are emphasizing that they do not care about it at all."},{"pos":"PHRASE 短语","cn":"几乎;差一点","en":"People use damn near to emphasize that what they are saying is not actually true, but is very close to being true.","ex":{"en":"I damn near went crazy","cn":"我当时都快要疯了。"}},{"pos":"PHRASE 短语","cn":"几乎;差不多","en":"Some people say as near as damn it or as near as dammit to emphasize that what they have said is almost completely accurate, but not quite.","ex":{"en":"It's as near as damn it the same thing","cn":"这几乎没什么分别。"}}]},"media":{"uk":"media/uk/damn__gb_1.mp3","us":"media/us/damn__us_1.mp3"},"examples":[{"en":"The film was damned by the critics for its mindless violence.","cn":"这部影片因无谓的暴力受到评论家的强烈指责。"},{"en":"Damn this machine! Why won't it work?","cn":"这该死的机器！怎么就是发动不起来？"}]},"database":{"media":{"uk":"media/uk/database__gb_1.mp3","us":"media/us/database__us_1.mp3"},"oxford":{"phon":"ˈdeɪtəbeɪs","pos":"noun","senses":[{"en":"an organized set of data that is stored in a computer and can be looked at and used in various ways","cn":"（存储在计算机中的）数据库","ex":{"en":"The database is updated monthly.","cn":"数据库每月更新。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(计算机)数据库，资料库","en":"A database is a collection of data that is stored in a computer and that can easily be used and added to.","ex":{"en":"They maintain a database of hotels that cater for businesswomen.","cn":"他们维护着一个服务于商界女性的酒店资料库。"}}]},"examples":[{"en":"customer details held on a database","cn":"存储在数据库内的客户详细信息"}]},"dancer":{"oxford":{"phon":"ˈdɑːnsə(r)","pos":"noun","senses":[{"en":"a person who dances or whose job is dancing","cn":"跳舞者；舞蹈演员","ex":{"en":"She's a fantastic dancer.","cn":"她的舞跳得非常好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"舞蹈演员;舞蹈家;跳舞者","en":"A dancer is a person who earns money by dancing, or a person who is dancing.","ex":{"en":"His previous girlfriend was a dancer with the Royal Ballet","cn":"他的前女友是皇家芭蕾舞团的舞蹈演员。"}},{"pos":"N-COUNT 可数名词","cn":"（出色或蹩脚的）舞者","en":"If you say that someone is a good dancer or a bad dancer, you are saying how well or badly they can dance.","ex":{"en":"He was the best dancer in LA.","cn":"他是洛杉矶舞跳得最好的人。"}}]},"media":{"uk":"media/uk/dancer__gb_1.mp3","us":"media/us/dancer__us_1.mp3"},"examples":[{"en":"He's a dancer with the Royal Ballet.","cn":"他是皇家芭蕾舞团的舞蹈演员。"},{"en":"She's a fantastic dancer.","cn":"她的舞跳得非常好。"}]},"damages":{"lemma":"damage","media":{"uk":"media/uk/damage__gb_1.mp3","us":"media/us/damage__us_1.mp3"}},"dainty":{"media":{"uk":"media/uk/dainty__gb_1.mp3","us":"media/us/dainty__us_1.mp3"},"oxford":{"phon":"ˈdeɪnti","pos":"adjective","senses":[{"en":"small and pretty in a way that people find attractive","cn":"娇小的；娇美的；精致的；小巧的","ex":{"en":"dainty feet","cn":"娇小可爱的脚"}},{"en":"careful, often in a way that suggests good manners","cn":"文雅的；优雅的；高雅的","ex":{"en":"She took a dainty little bite of the apple.","cn":"她文雅地咬了一小口苹果。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动作）文雅的;（人）娇小的，秀丽的;（物）小巧的，精致的","en":"If you describe a movement, person, or object as dainty, you mean that they are small, delicate, and pretty.","ex":{"en":"The girls were dainty and feminine.","cn":"这些女孩子娇美温柔。"}}]},"examples":[{"en":"She took a dainty little bite of the apple.","cn":"她文雅地咬了一小口苹果。"},{"en":"She blew her nose as daintily as possible.","cn":"她尽量文雅地擤了擤鼻涕。"}]},"daintily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"small - use this especially to show how you feel about someone or something, for example to show that you like them, dislike them, or feel sorry for them","cn":""},{"en":"a house, room etc that is compact is small but comfortable and convenient, because the space has been used effectively; a compact camera, computer etc is designed to be small and easy to carry","cn":""}]},"examples":[{"en":"a dainty gold chain","cn":"","src":"ld"},{"en":"a child with dainty features","cn":"","src":"ld"}],"media":{"uk":"media/uk/daintily__gb_1.mp3","us":"media/us/daintily__us_1.mp3"},"oxford":{"phon":"ˈdeɪntɪli","pos":"adverb","senses":[{"en":"in a careful way that suggests good manners","cn":"文雅的；优雅的；高雅的","ex":{"en":"She blew her nose as daintily as possible.","cn":"她以最优雅的姿态擤了擤鼻子。"}}]}},"dazzling":{"media":{"uk":"media/uk/dazzling__gb_1.mp3","us":"media/us/dazzling__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"辉煌的;灿烂的;艳丽的;动人的","en":"Something that is dazzling is very impressive or beautiful.","ex":{"en":"He gave Alberg a dazzling smile.","cn":"他冲着阿尔伯格粲然一笑。"}},{"pos":"ADJ 形容词","cn":"（光）炫目的，耀眼的","en":"A dazzling light is very bright and makes you unable to see properly for a short time.","ex":{"en":"He shielded his eyes against the dazzling declining sun.","cn":"他用手遮挡眼前落日耀眼的余晖。"}}]},"examples":[{"en":"a dazzling display of oriental dance","cn":"令人陶醉的东方舞蹈表演"},{"en":"a dazzling display of football skills","cn":"让人眼花缭乱的足球技巧表演"}],"oxford":{"phon":"ˈdæzlɪŋ","pos":"adjective","senses":[{"en":"so bright that you cannot see for a short time","cn":"（光）炫目的，使人眼花缭乱的","ex":{"en":"a dazzling white light","cn":"一道刺眼的白光"}},{"en":"impressing somebody very much","cn":"令人印象深刻的, 特别吸引人的","ex":{"en":"a dazzling display of oriental dance","cn":"令人目眩的东方舞蹈表演"}}]}},"damaging":{"media":{"uk":"media/uk/damaging__gb_1.mp3","us":"media/us/damaging__us_1.mp3"},"oxford":{"phon":"ˈdæmɪdʒɪŋ","pos":"adjective","senses":[{"en":"causing damage; having a bad effect on somebody/something","cn":"造成破坏的；有害的；损害的","ex":{"en":"damaging consequences/effects","cn":"破坏性的后果／影响"}}]},"examples":[{"en":"Lead is potentially damaging to children's health.","cn":"铅对儿童的健康具有潜在损害。"},{"en":"damaging consequences/effects","cn":"破坏性的后果/影响"}],"base":"damage"},"dad":{"media":{"uk":"media/uk/dad__gb_1.mp3","us":"media/us/dad__us_1.mp3"},"oxford":{"phon":"dæd","pos":"noun","senses":[{"en":"father","cn":"爸爸","ex":{"en":"That's my dad over there.","cn":"那边那位是我爸爸。"}}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"爸爸;老爸","en":"Your dad is your father.","ex":{"en":"How do you feel, Dad?","cn":"爸爸，你感觉怎么样？"}}]},"examples":[{"en":"Do you live with your mum or your dad?","cn":"你和妈妈还是和爸爸住在一起？"},{"en":"Is it OK if I borrow the car, Dad?","cn":"爸爸，借用一下汽车好吗？"}]},"dawn":{"media":{"uk":"media/uk/dawn__gb_1.mp3","us":"media/us/dawn__us_1.mp3"},"oxford":{"phon":"dɔːn","pos":"noun","senses":[{"en":"the time of day when light first appears","cn":"黎明；拂晓；破晓；天亮","g":"[uncountable, countable]","ex":{"en":"They start work at dawn.","cn":"天一亮他们就开始干活了。"}},{"en":"the beginning or first signs of something","cn":"开端；曙光；萌芽","g":"[singular]","ex":{"en":"the dawn of civilization/time/history","cn":"文明／时代／历史的开端"}},{"en":"to begin","cn":"开始","g":"[intransitive]","ex":{"en":"The following morning dawned bright and warm.","cn":"第二天一大早阳光和煦。"},"pos":"verb"},{"en":"to become obvious or easy to understand","cn":"变得明朗；开始清楚","g":"[intransitive]","ex":{"en":"Slowly the awful truth dawned.","cn":"可怕的事实慢慢地清晰起来。"},"pos":"verb"},{"en":"a first name for girls","cn":"道恩，丹（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"黎明;拂晓","en":"Dawn is the time of day when light first appears in the sky, just before the sun rises.","ex":{"en":"Nancy woke at dawn.","cn":"拂晓时分南希醒了。"}},{"pos":"N-SING 单数名词","cn":"开端;起始阶段","en":"The dawn of a period of time or a situation is the beginning of it.","ex":{"en":"We can only guess what went through the mind of a man who could look back to the dawn of powered flight.","cn":"一个能够回想起动力飞行初始阶段的人那时脑子里想了些什么，我们只能够猜测而已。"}},{"pos":"VERB 动词","cn":"初现;出现;开始形成","en":"If something is dawning, it is beginning to develop or come into existence.","ex":{"en":"Throughout Europe a new railway age, that of the high-speed train, has dawned","cn":"新的铁路时代——高速铁路时代，在整个欧洲已经开始出现。"}},{"pos":"VERB 动词","cn":"(一天）到来，开始","en":"When you say that a particular day dawned, you mean it arrived or began, usually when it became light.","ex":{"en":"When the great day dawned, the first concern was the weather","cn":"当那个不同寻常的日子到来时，大家首先关注的是天气。"}},{"pos":"","cn":"","en":"at the crack of dawn→see: ;"},{"pos":"","cn":"","en":"相关词组：dawn on"}]},"examples":[{"en":"Peace marked a new dawn in the country's history.","cn":"和平使这个国家的历史翻开了新的一页。"},{"en":"Suddenly it dawned on me that they couldn't possibly have met before.","cn":"我突然明白他们以前不可能见过面。"}]},"daytime":{"media":{"uk":"media/uk/daytime__gb_1.mp3","us":"media/us/daytime__us_1.mp3"},"oxford":{"phon":"ˈdeɪtaɪm","pos":"noun","senses":[{"en":"the period during the day between the time when it gets light and the time when it gets dark","cn":"白天；白昼；日间","ex":{"en":"You don't often see this bird in (the) daytime.","cn":"这种鸟白天不常见。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"白天;日间","en":"The daytime is the part of a day between the time when it gets light and the time when it gets dark.","ex":{"en":"In the daytime he stayed up in his room, sleeping, or listening to music","cn":"他白天呆在自己的屋子里睡觉或听音乐。"}},{"pos":"ADJ 形容词","cn":"(电视或广播节目周一至周五)白天播出的，日间播放的","en":"Daytime television and radio is broadcast during the morning and afternoon on weekdays.","ex":{"en":"...ITV's new package of daytime programmes.","cn":"独立电视台的新一整套日间档节目"}}]},"examples":[{"en":"Daytime temperatures never fell below 30°C.","cn":"日间温度从未低于 30 摄氏度。"},{"en":"Please give your name and daytime phone number.","cn":"请提供姓名和日间联络电话。"}]},"daring":{"media":{"uk":"media/uk/daring__gb_1.mp3","us":"media/us/daring__us_1.mp3"},"oxford":{"phon":"ˈdeərɪŋ","pos":"adjective","senses":[{"en":"brave; willing to do dangerous or unusual things; involving danger or taking risks","cn":"勇敢的；敢于冒险的","ex":{"en":"a daring walk in space","cn":"勇敢的太空漫步"}},{"en":"courage and the quality of being willing to take risks if necessary","cn":"大胆；勇敢；胆量","ex":{"en":"the skill and daring of the mountain climbers","cn":"登山者的技能和胆量"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大胆的;敢于冒险的;勇于创新的","en":"People who are daring are willing to do or say things which are new or which might shock or anger other people.","ex":{"en":"Bergit was probably more daring than I was","cn":"伯吉特可能比我更敢于冒险。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大胆的;勇敢的;英勇的","en":"A daring person is willing to do things that might be dangerous.","ex":{"en":"...the heroic and daring Charlie Pierce","cn":"英勇无畏的查利·皮尔斯"}},{"pos":"N-UNCOUNT 不可数名词","cn":"胆量;勇气;冒险精神","en":"Daring is the courage to do things which might be dangerous or which might shock or anger other people.","ex":{"en":"His daring may have cost him his life.","cn":"他的冒险可能让他断送了性命。"}}]},"examples":[{"en":"There are plenty of activities at the resort for the less daring.","cn":"度假胜地有许多活动是供不太敢于冒险的人玩的。"},{"en":"The gallery was known for putting on daring exhibitions.","cn":"陈列馆以其别具一格的展品而享有盛名。"}],"base":"dare"},"damnation":{"media":{"uk":"media/uk/damnation__gb_1.mp3","us":"media/us/damnation__us_1.mp3"},"oxford":{"phon":"dæmˈneɪʃn","pos":"noun","senses":[{"en":"the state of being in hell; the act of sending somebody to hell","cn":"天谴；罚入地狱","ex":{"en":"eternal damnation","cn":"永罚"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(某些宗教中人死后的)罚入地狱","en":"According to some religions, if someone suffers damnation, they have to stay in hell for ever after they have died because of their sins.","ex":{"en":"...a fear of eternal damnation.","cn":"对死后永堕地狱的恐惧"}},{"pos":"EXCLAM 感叹语","cn":"(表示愤怒或不耐烦) 该死，见鬼去吧","en":"Some people say 'damnation!' to express anger or impatience."}]},"examples":[{"en":"eternal damnation","cn":"永罚"}]},"day":{"media":{"uk":"media/uk/day__gb_1.mp3","us":"media/us/day__us_1.mp3"},"oxford":{"phon":"deɪ","pos":"noun","senses":[{"en":"a period of 24 hours","cn":"一天；一日","g":"[countable]","ex":{"en":"‘What day is it today?’ ‘Monday.’","cn":"“今天星期几？”“星期一。”"}},{"en":"the time between when it becomes light in the morning and when it becomes dark in the evening","cn":"白昼；白天","g":"[countable, uncountable]","ex":{"en":"What a beautiful day!","cn":"多么美好的一天！"}},{"en":"the hours of the day when you are active, working, etc., not sleeping","cn":"工作日；一天的活动时间","g":"[countable, usually singular]","lab":"especially North American English","ex":{"en":"a seven-hour working day","cn":"七小时工作日"}},{"en":"a particular period of time or history","cn":"时期；时代","g":"[countable, usually plural]","lab":"informal","ex":{"en":"in Queen Victoria’s day","cn":"在维多利亚女王时代"}},{"en":"a particular period in somebody's life or career","cn":"（人生或职业生涯的）时期，阶段","g":"[plural]","ex":{"en":"I have many happy memories from my student days.","cn":"我的学生时代留下了许多美好的回忆。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（一周中的）一日，一天","en":"A day is one of the seven twenty-four hour periods of time in a week."},{"pos":"N-VAR 可变名词","cn":"昼;白天","en":"Day is the time when it is light, or the time when you are up and doing things.","ex":{"en":"The weather did not help; hot by day, cold at night","cn":"天气也不肯帮忙：白天很热，晚上很冷。"}},{"pos":"N-COUNT 可数名词","cn":"时期;时代","en":"You can refer to a particular period in history as a particular day or as particular days .","ex":{"en":"He began to talk about the Ukraine of his uncle's day","cn":"他开始讲述他叔叔那个时代的乌克兰。"}},{"pos":"PHRASE 短语","cn":"日复一日;一天又一天","en":"If something happens day after day, it happens every day without stopping.","ex":{"en":"The newspaper job had me doing the same thing day after day.","cn":"这份报社的工作让我日复一日地做着同样的事。"}},{"pos":"PHRASE 短语","cn":"如今;在当代;在今天这个时代","en":"In this day and age means in modern times.","ex":{"en":"Even in this day and age the old attitudes persist.","cn":"即使在今天这个时代，这些陈旧的观念依然存在。"}},{"pos":"PHRASE 短语","cn":"破旧;陈旧;状况不佳","en":"If you say that something has seen better days, you mean that it is old and in poor condition.","ex":{"en":"The tweed jacket she wore had seen better days.","cn":"她穿的那件粗花呢夹克已经很旧了。"}},{"pos":"PHRASE 短语","cn":"到此为止;结束","en":"If you call it a day, you decide to stop what you are doing because you are tired of it or because it is not successful.","ex":{"en":"Faced with mounting debts, the decision to call it a day was inevitable","cn":"面对着不断增加的债务，最终难免作出将其结束的决定。"}},{"pos":"PHRASE 短语","cn":"(在战斗、辩论或体育竞赛中）获胜，取胜","en":"If someone carries the day, they are the winner in a contest such as a battle, debate, or sporting competition.","ex":{"en":"For the time being, the liberals seem to have carried the day.","cn":"眼下似乎是自由主义者占据了上风。"}},{"pos":"PHRASE 短语","cn":"已过全盛时期;风光不再;不再流行","en":"If you say that something has had its day, you mean that the period during which it was most successful or popular has now passed.","ex":{"en":"Beat music may finally have had its day","cn":"强节奏摇滚乐的黄金时期或许已经终结。"}},{"pos":"PHRASE 短语","cn":"使…非常高兴","en":"If something makes your day, it makes you feel very happy.","ex":{"en":"Come on, Bill. Send Tom a card and make his day","cn":"来吧，比尔。给汤姆寄张卡片让他高兴高兴吧。"}},{"pos":"PHRASE 短语","cn":"日日夜夜;夜以继日","en":"If something happens day and night or night and day, it happens all the time without stopping.","ex":{"en":"Chantal kept a fire burning night and day","cn":"尚塔尔让一堆火日夜不熄地一直燃着。"}},{"pos":"PHRASE 短语","cn":"将来有一天;总有一天;有朝一日","en":"One day or some day or one of these days means at some time in the future.","ex":{"en":"I too dreamed of living in London one day","cn":"我也梦想过将来有一天能住在伦敦。"}},{"pos":"PHRASE 短语","cn":"几天前;前两天","en":"If you say that something happened the other day, you mean that it happened a few days ago.","ex":{"en":"I phoned your office the other day","cn":"几天前我给你的办公室打过电话。"}},{"pos":"PHRASE 短语","cn":"挽回局面;扭转败局;转危为安;反败为胜","en":"If someone or something saves the day in a situation which seems likely to fail, they manage to make it successful.","ex":{"en":"...this story about how he saved the day at his daughter's birthday party","cn":"这个关于他如何在女儿的生日聚会上成功挽回局面的故事"}},{"pos":"PHRASE 短语","cn":"每天;天天;逐日","en":"If something happens from day to day or day by day, it happens each day.","ex":{"en":"Your needs can differ from day to day","cn":"你的需要每天可能都会不同。"}},{"pos":"PHRASE短语","cn":"正好;恰好;一天不差","en":"If it is a month or a year to the day since a particular thing happened, it is exactly a month or a year since it happened.","ex":{"en":"It was January 19, a year to the day since he had arrived in Singapore","cn":"那天是 1月 19 号，他到新加坡正好一年的日子。"}},{"pos":"PHRASE 短语","cn":"至今;直到现在","en":"To this day means up until and including the present time.","ex":{"en":"To this day young Zulu boys practise fighting.","cn":"直到现在年轻的祖鲁男孩还练习格斗。"}},{"pos":"PHRASE 短语","cn":"获胜/失败","en":"If a particular person, group, or thing wins the day, they win a battle, struggle, or competition. If they lose the day, they are defeated.","ex":{"en":"His determination and refusal to back down had won the day","cn":"他的坚定和拒不退让使他赢得了胜利。"}},{"pos":"PHRASE 短语","cn":"(困难的任务)日常工作一部分的，常有的，难免的","en":"If you say that a task is all in a day's work for someone, you mean that they do not mind doing it although it may be difficult, because it is part of their job or because they often do it.","ex":{"en":"For war reporters, dodging snipers' bullets is all in a day's work","cn":"对于战地记者来说，躲避狙击手的子弹是家常便饭。"}},{"pos":"","cn":"","en":"your day in court→see: ; it's early days→see: ; at the end of the day→see: ; late in the day→see: ; to the light of day→see: ; someone's days are numbered→see: ; the good old days→see: ; to pass the time of day→see: ;"}]},"examples":[{"en":"They live from day to day, looking after their sick daughter.","cn":"他们过一天算一天，日复一日地照顾着生病的女儿。"},{"en":"My car broke down and then I locked myself out — it's just not my day!","cn":"我的汽车抛锚了，我又没带钥匙，真是祸不单行！"}]},"dandelion":{"oxford":{"phon":"ˈdændɪlaɪən","pos":"noun","senses":[{"en":"a small wild plant with a bright yellow flower that becomes a soft white ball of seeds called a dandelion clock","cn":"蒲公英"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蒲公英","en":"A dandelion is a wild plant which has yellow flowers with lots of thin petals. When the petals of each flower drop off, a fluffy white ball of seeds grows."}]},"media":{"img":["media/pic/plantlabels_plants_comp.jpg","media/thumb/dandelion.jpg"],"uk":"media/uk/dandelion__gb_1.mp3","us":"media/us/dandelion__us_1.mp3"}},"dancing":{"media":{"uk":"media/uk/dancing__gb_1.mp3","us":"media/us/dancing__us_1.mp3"},"oxford":{"phon":"ˈdɑːnsɪŋ","pos":"noun","senses":[{"en":"moving your body to music","cn":"跳舞；舞蹈","ex":{"en":"There was music and dancing till two in the morning.","cn":"音乐和舞蹈一直持续到凌晨两点。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"跳舞;舞蹈","en":"When people dance for enjoyment or to entertain others, you can refer to this activity as dancing .","ex":{"en":"All the schools have music and dancing as part of the curriculum","cn":"所有学校都设有音乐和舞蹈课。"}}]},"examples":[{"en":"There was music and dancing till two in the morning.","cn":"音乐和舞蹈一直持续到凌晨两点。"},{"en":"dancing classes","cn":"舞蹈课"}],"base":"dance"},"darling":{"media":{"uk":"media/uk/darling__gb_1.mp3","us":"media/us/darling__us_1.mp3"},"oxford":{"phon":"ˈdɑːlɪŋ","pos":"noun","senses":[{"en":"a way of addressing somebody that you love","cn":"亲爱的；宝贝","lab":"informal","ex":{"en":"What's the matter, darling?","cn":"怎么啦，亲爱的？"}},{"en":"a person who is very friendly and kind","cn":"亲切友好的人","ex":{"en":"You are a darling, Hugo.","cn":"雨果，你真好。"}},{"en":"a person who is especially liked and very popular","cn":"备受宠爱的人；宠儿","ex":{"en":"She is the darling of the newspapers and can do no wrong.","cn":"她是新闻界的大红人，不可能做错事的。"}},{"en":"much loved; very attractive, special, etc.","cn":"备受喜爱的；可爱的；迷人的","ex":{"en":"My darling daughter.","cn":"我的宝贝女儿。"},"pos":"adjective"},{"en":"very pretty and pleasing","cn":"亲切友好的人","ex":{"en":"What a darling little hat!","cn":"多么可爱的小帽子啊！"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VOC 称呼名词","cn":"(用作昵称）亲爱的，宝贝儿","en":"You call someone darling if you love them or like them very much.","ex":{"en":"Thank you, darling","cn":"谢谢你，亲爱的。"}},{"pos":"N-VOC 称呼名词","cn":"(英国一些地方用于表示友善的称呼）亲爱的","en":"In some parts of Britain, people call other people darling as a sign of friendliness."},{"pos":"ADJ 形容词","cn":"可爱的;迷人的;钟爱的","en":"Some people use darling to describe someone or something that they love or like very much.","ex":{"en":"To have a darling baby boy was the greatest gift I could imagine","cn":"生一个可爱的男孩是我能想到的最好的礼物。"}},{"pos":"N-COUNT 可数名词","cn":"可爱的人;好心的人","en":"If you describe someone as a darling, you are fond of them and think that they are nice.","ex":{"en":"He's such a darling.","cn":"他真是个可爱的人。"}},{"pos":"N-COUNT 可数名词","cn":"宠儿;备受喜爱的人","en":"The darling of a group of people is someone who is especially liked by that group.","ex":{"en":"Rajneesh was the darling of a prosperous family.","cn":"罗杰尼希是一个富有家庭的宠儿。"}}]},"examples":[{"en":"She is the darling of the newspapers and can do no wrong.","cn":"她是新闻界的大红人，不可能做错事的。"},{"en":"‘Darling Henry,’ the letter began. “","cn":"亲爱的亨利”，信的开头这样写道。"}]},"daughter":{"media":{"uk":"media/uk/daughter__gb_1.mp3","us":"media/us/daughter__us_1.mp3"},"oxford":{"phon":"ˈdɔːtə(r)","pos":"noun","senses":[{"en":"a person’s female child","cn":"女儿","lab":"especially US English","ex":{"en":"We have two sons and a daughter.","cn":"我们有两个儿子，一个女儿。"}},{"en":"a woman who belongs to a particular place or country, etc.","cn":"（某地、某国等的）妇女","lab":"literary","ex":{"en":"one of the town’s most famous daughters","cn":"这座城镇最著名的女性之一"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女儿","en":"Someone's daughter is their female child.","ex":{"en":"...Flora and her daughter Catherine.","cn":"弗洛拉和她的女儿凯瑟琳"}}]},"examples":[{"en":"She's the daughter of an Oxford professor.","cn":"她是牛津大学一位教授的女儿。"},{"en":"They have three grown-up daughters.","cn":"他们有三个成年的女儿。"}]},"daily":{"media":{"uk":"media/uk/daily__gb_1.mp3","us":"media/us/daily__us_1.mp3"},"oxford":{"phon":"ˈdeɪli","pos":"adjective","senses":[{"en":"happening, done or produced every day","cn":"每日的；日常的","ex":{"en":"Many people still read a daily newspaper.","cn":"很多人依然会看日报。"}},{"en":"connected with one day’s work","cn":"每个工作日的；按日的","ex":{"en":"They charge a daily rate.","cn":"他们按日收费。"}},{"en":"every day","cn":"每日；每天","ex":{"en":"The machines are inspected twice daily.","cn":"机器每日检查两次。"},"pos":"adverb"},{"en":"a newspaper published every day except Sunday","cn":"（除星期日外每日发行的）日报","ex":{"en":"The story was in all the dailies.","cn":"这则新闻刊登在所有日报上。"},"pos":"noun"},{"en":"a person employed to come to somebody’s house each day to clean it and do other jobs","cn":"（不寄宿的）仆人","lab":"British English, old-fashioned，，","pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"每日;每天","en":"If something happens daily, it happens every day.","ex":{"en":"Cathay Pacific flies daily non-stop to Hong Kong from Heathrow","cn":"国泰航空公司每天都有从希思罗机场直飞香港的航班。"}},{"pos":"ADJ 形容词","cn":"一天的;按天计算的","en":"Daily quantities or rates relate to a period of one day.","ex":{"en":"...a diet containing adequate daily amounts of fresh fruit","cn":"包含了足量一天所需新鲜水果的饮食"}},{"pos":"N-COUNT 可数名词","cn":"日报","en":"A daily is a newspaper that is published every day of the week except Sunday.","ex":{"en":"Copies of the local daily had been scattered on a table.","cn":"几份当地的日报散放在桌子上。"}},{"pos":"PHRASE 短语","cn":"日常生活","en":"Your daily life is the things that you do every day as part of your normal life.","ex":{"en":"...the failure of the government to improve most people's daily lives.","cn":"政府没能改善大多数人的日常生活"}}]},"examples":[{"en":"events affecting the daily lives of millions of people","cn":"影响数百万人日常生活的事件"},{"en":"The story was in all the dailies.","cn":"这则新闻刊登在所有日报上。"}]},"data":{"media":{"uk":"media/uk/data__gb_1.mp3","us":"media/us/data__us_1.mp3"},"oxford":{"phon":"ˈdeɪtə","pos":"noun","senses":[{"en":"facts or information, especially when examined and used to find out things or to make decisions","cn":"数据；资料；材料","g":"[uncountable, plural]","lab":"specialist","ex":{"en":"We collected publicly available data over a 10-day period.","cn":"我们在 10 天时间里收集了公开发表的数据。"}},{"en":"information that is stored by a computer","cn":"（存储在计算机中的）数据资料","g":"[uncountable]","ex":{"en":"All this data is stored on hundreds of servers in San Francisco.","cn":"所有这些数据都存储在旧金山的数百台服务器上。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT; also N-PLURAL 不可数名词；复数名词","cn":"（尤指可用于分析的）资料，材料，数据（美国英语中通常用作复数名词;在专业或正式的英国英语中有时用作复数名词，有时用作不可数名词)","en":"You can refer to information as data, especially when it is in the form of facts or statistics that you can analyse. In American English, data is usually a plural noun. In technical or formal British English, data is sometimes a plural noun, but at other times, it is an uncount noun.","ex":{"en":"The study was based on data from 2,100 women","cn":"这项研究基于从 2,100 名女性那里收集来的资料。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(可存储并为计算机程序所用的）数据","en":"Data is information that can be stored and used by a computer program.","ex":{"en":"You can compress huge amounts of data on to a CD-ROM.","cn":"可以把大量的数据压缩到一张CD-ROM上。"}}]},"examples":[{"en":"This data was collected from 69 countries.","cn":"这资料是从 69 个国家收集来的。"},{"en":"raw data (= that has not been analysed)","cn":"原始资料"}]},"dated":{"media":{"uk":"media/uk/dated__gb_1.mp3","us":"media/us/dated__us_1.mp3"},"oxford":{"phon":"ˈdeɪtɪd","pos":"adjective","senses":[{"en":"old-fashioned; belonging to a time in the past","cn":"过时的；陈旧的","ex":{"en":"Those TV comedies were OK in their day but seem incredibly dated now.","cn":"那些电视喜剧当时觉得还不错，现在看来就太过时了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的;落伍的;不时兴的","en":"Dated things seem old-fashioned, although they may once have been fashionable or modern.","ex":{"en":"...people in dated dinner-jackets.","cn":"身着过时的无尾礼服的人们"}}]},"examples":[{"en":"That dress looks a bit dated now.","cn":"那件连衣裙现在看起来有点过时了。"}],"base":"date"},"dashboard":{"media":{"uk":"media/uk/dashboard__gb_1.mp3","us":"media/us/dashboard__us_1.mp3","img":["media/thumb/dashboard.jpg"]},"oxford":{"phon":"ˈdæʃbɔːd","pos":"noun","senses":[{"en":"the part of a car in front of the driver that has instruments and controls in it","cn":"（汽车上的）仪表板","lab":"informal"},{"en":"a diagram that shows important information, typically one that gives an outline of a business","cn":"（主要业务数据的）动态监控面板","ex":{"en":"an executive dashboard showing key performance indicators","cn":"显示关键运营指标的监控管理面板"}},{"en":"a page on a website where you can access information about its various functions","cn":"（网站的）主控面板（从中可以了解网站的不同功能）","ex":{"en":"I like all of my blogs under one dashboard.","cn":"我喜欢将我的所有博客放在一个仪表板下。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车的）仪表板","en":"The dashboard in a car is the panel facing the driver's seat where most of the instruments and switches are."}]}},"date":{"media":{"uk":"media/uk/date__gb_1.mp3","us":"media/us/date__us_1.mp3"},"oxford":{"phon":"deɪt","pos":"noun","senses":[{"en":"a particular day of the month, sometimes in a particular year, given in numbers and words","cn":"日期；日子","g":"[countable]","lab":"especially North American English","sc":"particular day/year","ex":{"en":"‘What's the date today?’ ‘The 10th.’","cn":"“今天几号？”“10 号。”"}},{"en":"a particular day or year when a particular event happened or will happen","cn":"（某事件发生的）日期，年份","sc":"particular day/year","ex":{"en":"1066 is the most famous date in English history.","cn":"1066 年是英国历史上最著名的年份。"}},{"en":"a time in the past or future that is not a particular day","cn":"年代；时期；时候","g":"[singular, uncountable]","sc":"past time/future","ex":{"en":"The details can be added at a later date.","cn":"细节可过些时候再补充进去。"}},{"en":"an arrangement to meet somebody at a particular time","cn":"会晤时间；约见时间","g":"[countable]","sc":"arrangement to meet","ex":{"en":"Call me next week and we'll try and make a date.","cn":"下周打电话给我，我们争取定个见面时间。"}},{"en":"a meeting that you have arranged with a boyfriend or girlfriend or with somebody who might become a boyfriend or girlfriend","cn":"约会；情侣约会","g":"[countable]","lab":"especially North American English","sc":"romantic meeting","ex":{"en":"I've got a date with Lucy tomorrow night.","cn":"明天晚上我与露西有个约会。"}},{"en":"a boyfriend or girlfriend with whom you have arranged a date","cn":"约会对象","g":"[countable]","sc":"romantic meeting","ex":{"en":"My date is meeting me at seven.","cn":"我的对象七点钟与我见面。"}},{"en":"a sweet sticky brown fruit that grows on a tree called a date palm, common in North Africa and West Asia","cn":"（北非和西亚常见的海枣树的）海枣，椰枣","g":"[countable]","sc":"fruit"},{"en":"to write or print the date on something","cn":"注明日期；写上日期","g":"[transitive, often passive]","sc":"write date","ex":{"en":"Thank you for your letter dated 24th March.","cn":"你 3 月 24 日来函收悉，谢谢。"},"pos":"verb"},{"en":"to say when something old existed or was made","cn":"确定年代","g":"[transitive, often passive]","sc":"find age","ex":{"en":"It has not yet been possible to date the paintings accurately.","cn":"一直无法准确鉴定这些画作的年代。"},"pos":"verb"},{"en":"to become old-fashioned","cn":"过时；不流行","g":"[intransitive]","sc":"of clothes/words","ex":{"en":"She designs classic clothes which do not date.","cn":"她设计的服装式样古朴，不会过时。"},"pos":"verb"},{"en":"if something dates you, it shows that you are fairly old or older than the people you are with","cn":"使显老；使显得年龄大","g":"[transitive]","sc":"person","ex":{"en":"I was at the Woodstock festival—that dates me, doesn't it?","cn":"我参加了伍德斯托克摇滚音乐节，那说明我老了，是不是？"},"pos":"verb"},{"en":"to have a romantic relationship with somebody","cn":"与（某人）谈恋爱","g":"[transitive, intransitive]","sc":"have relationship","ex":{"en":"She's been dating Ron for several months.","cn":"她与罗恩谈恋爱已有数月。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"日期;日子","en":"A date is a specific time that can be named, for example a particular day or a particular year.","ex":{"en":"What's the date today?","cn":"今天是几号？"}},{"pos":"VERB 动词","cn":"确定…的日期(或年代)","en":"If you date something, you give or discover the date when it was made or when it began.","ex":{"en":"You cannot date the carving and it is difficult to date the stone itself","cn":"无法确定这一雕刻的年代，连石头本身的年代都难以判断。"}},{"pos":"VERB 动词","cn":"在（信件、支票等）上注明日期","en":"When you date something such as a letter or a cheque, you write that day's date on it.","ex":{"en":"Once the decision is reached, he can date and sign the sheet","cn":"一旦决议达成，他就可以在这张纸上签署日期和姓名了。"}},{"pos":"N-SING 单数名词","cn":"在（某个）日期;在（某个）时间","en":"If you want to refer to an event without saying exactly when it will happen or when it happened, you can say that it will happen or happened at some date in the future or past.","ex":{"en":"Retain copies of all correspondence, since you may need them at a later date","cn":"要保留好所有信件的副本，日后可能会用到。"}},{"pos":"PHRASE 短语","cn":"迄今;到目前为止","en":"To date means up until the present time.","ex":{"en":"'Dottie' is by far his best novel to date","cn":"《多蒂》是他迄今为止最好的小说。"}},{"pos":"VERB 动词","cn":"过时;落伍","en":"If something dates, it goes out of fashion and becomes unacceptable to modern tastes.","ex":{"en":"A black coat always looks smart and will never date","cn":"黑色外套看起来总是很潇洒，而且永远也不会落伍。"}},{"pos":"VERB 动词","cn":"使显老;使显出年龄大","en":"If your ideas, what you say, or the things that you like or can remember date you, they show that you are quite old or older than the people you are with.","ex":{"en":"It's going to date me now. I attended that school from 1969 to 1972.","cn":"现在说起来我就显老了。我 1969至 1972 年就读于那所学校。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指男女间的）约会","en":"A date is an appointment to meet someone or go out with them, especially someone with whom you are having, or may soon have, a romantic relationship.","ex":{"en":"I have a date with Bob","cn":"我和鲍勃有个约会。"}},{"pos":"N-COUNT 可数名词","cn":"约会对象","en":"If you have a date with someone with whom you are having, or may soon have, a romantic relationship, you can refer to that person as your date .","ex":{"en":"He lied to Essie, saying his date was one of the girls in the show.","cn":"他对埃茜撒谎说跟他约会的是参加演出的一个女孩。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）约会","en":"If you are dating someone, you go out with them regularly because you are having, or may soon have, a romantic relationship with them. You can also say that two people are dating.","ex":{"en":"For a year I dated a woman who was a research assistant","cn":"我曾与一位女研究助理约会了一年的时间。"}},{"pos":"N-COUNT 可数名词","cn":"海枣（果）","en":"A date is a small, dark-brown, sticky fruit with a stone inside. Dates grow on palm trees in hot countries."},{"pos":"","cn":"","en":"相关词组：date back date from"}]},"examples":[{"en":"I was at the Woodstock festival — that dates me, doesn't it?","cn":"我参加了伍德斯托克摇滚音乐节，那说明我老了，是不是？"},{"en":"To date, we have received over 200 replies.","cn":"到目前为止，我们已收到 200 多封回信。"}]},"danish":{"media":{"uk":"media/uk/danish_1_gb_1.mp3","us":"media/us/danish_1_us_1.mp3"},"oxford":{"phon":"ˈdeɪnɪʃ","pos":"adjective","senses":[{"en":"from or connected with Denmark","cn":"丹麦的"},{"en":"the language of Denmark","cn":"丹麦语","g":"[uncountable]","pos":"noun"},{"en":"a sweet cake made of light pastry, often containing apple, nuts, etc. and/or covered with icing","cn":"丹麦酥皮甜饼","g":"[countable]","lab":"North American English, British English，，","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"丹麦的;丹麦人的;丹麦语（或文化）的","en":"Danish means belonging or relating to Denmark, its people, its language, or culture.","ex":{"en":"...the Danish coast","cn":"丹麦海岸"}},{"pos":"N-UNCOUNT 不可数名词","cn":"丹麦语","en":"Danish is the language spoken in Denmark."}]}},"dampener":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"put a dampener on 同 put a damper on","en":"To put a dampener on something means the same as to put a damper on it.","ex":{"en":"Boy, did this woman know how to put a dampener on your day.","cn":"天啊，这个女人可真会让人扫兴。"}}]},"oxford":{"phon":"ˈdæmpnə(r)","pos":"noun","senses":[{"en":"a thing that makes something less pleasant, successful, etc.","cn":"使人扫兴（或沮丧）的事物；起阻碍作用的事物","ex":{"en":"Lily isn't letting motherhood put a dampener on her social life.","cn":"莉莉并没有让母亲身份影响她的社交生活。"}}]}},"day-to-day":{"oxford":{"phon":"ˌdeɪ tə ˈdeɪ","pos":"adjective","senses":[{"en":"planning for only one day at a time","cn":"按日计划的；逐日的；每天的","ex":{"en":"I have organized the cleaning on a day-to-day basis, until our usual cleaner returns.","cn":"我已逐日安排好清洁工作，直到我们的清洁工回来为止。"}},{"en":"involving the usual events or tasks of each day","cn":"日常工作的；例行的","ex":{"en":"She has been looking after the day-to-day running of the school.","cn":"她一直在负责学校的日常管理工作。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"每天的;日常的","en":"Day-to-day things or activities exist or happen every day as part of ordinary life.","ex":{"en":"I am a vegetarian and use a lot of lentils in my day-to-day cooking.","cn":"我是个素食主义者，日常烹饪时会用到很多小扁豆。"}}]},"media":{"uk":"media/uk/day_to_day_1_gb_1.mp3","us":"media/us/day_to_day_1_us_1.mp3"},"examples":[{"en":"I have organized the cleaning on a day-to-day basis , until our usual cleaner returns.","cn":"我已逐日安排好清洁工作，直到我们的清洁工回来为止。"},{"en":"She has been looking after the day-to-day running of the school.","cn":"她一直在负责学校的日常管理工作。"}]},"dangerous":{"media":{"uk":"media/uk/dangerous__gb_1.mp3","us":"media/us/dangerous__us_1.mp3"},"oxford":{"phon":"ˈdeɪndʒərəs","pos":"adjective","senses":[{"en":"likely to injure or harm somebody, or to damage or destroy something","cn":"有危险的；引起危险的；不安全的","lab":"British English","ex":{"en":"The situation is extremely dangerous.","cn":"情况极其危险。"}},{"en":"likely to cause problems or have a bad result","cn":"可能出问题的；可能带来恶果的","ex":{"en":"This ruling sets a dangerous precedent.","cn":"这项裁决开了一个危险的先例。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"危险的;可能带来危害的;不安全的","en":"If something is dangerous, it is able or likely to hurt or harm you.","ex":{"en":"It's a dangerous stretch of road.","cn":"那段路很不安全。"}}]},"examples":[{"en":"We'd be on dangerous ground if we asked about race or religion.","cn":"我们要是问到种族或宗教问题，就很可能会冒犯人。"},{"en":"The traffic here is very dangerous for children.","cn":"这里的交通对孩子很危险。"}]},"dandelions":{"lemma":"dandelion","media":{"img":["media/ldoce/img/dandelions.jpg"]}},"damp":{"oxford":{"phon":"dæmp","pos":"adjective","senses":[{"en":"slightly wet, often in a way that is unpleasant","cn":"潮湿的；微湿的；湿气重的","ex":{"en":"The cottage was cold and damp.","cn":"这小屋又冷又湿。"}},{"en":"the state of being slightly wet ; areas on a wall, etc. that are slightly wet","cn":"潮湿；潮气；湿气；潮渍","ex":{"en":"The old house smells of damp.","cn":"这老房子散发出一股潮气。"},"pos":"noun"},{"en":"to make something slightly wet","cn":"弄湿；使潮湿","lab":"more frequent","ex":{"en":"She damped a towel and wrapped it round his leg.","cn":"她弄湿毛巾，把它裹在他的腿上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"潮湿的;微湿的;湿气重的","en":"Something that is damp is slightly wet.","ex":{"en":"Her hair was still damp","cn":"她的头发还有点儿湿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（内墙面上、空气中等处的）湿气，潮气","en":"Damp is moisture that is found on the inside walls of a house or in the air.","ex":{"en":"There was damp everywhere and the entire building was in need of rewiring.","cn":"到处都受了潮，整栋楼需要重新布线。"}},{"pos":"VERB 动词","cn":"使潮湿;弄湿","en":"If you damp something, you make it slightly wet.","ex":{"en":"Hillsden damped a hand towel and laid it across her forehead.","cn":"希尔斯登沾湿了一条手巾，将它敷在她的额头上。"}},{"pos":"","cn":"","en":"相关词组：damp down"}]},"media":{"uk":"media/uk/damp__gb_1.mp3","us":"media/us/damp__us_1.mp3"},"examples":[{"en":"Those marks above the window look like damp to me.","cn":"窗子上面的那些印迹看上去像是水渍。"},{"en":"She damped a towel and wrapped it round his leg.","cn":"她弄湿毛巾，把它裹在他的腿上。"}]},"dashed":{"media":{"uk":"media/uk/dashed__gb_1.mp3","us":"media/us/dashed__us_1.mp3"},"oxford":{"phon":"dæʃt","pos":"adjective","senses":[{"en":"used as a mild swear word by some people to emphasize something or to show they are annoyed","cn":"（表示强调或不耐烦）该死的，讨厌的"},{"en":"made of dashes with spaces in between","cn":"短划线的；虚的","ex":{"en":"The dashed lines show the expected values for each population.","cn":"虚线显示每个群体的预期值。"}}]},"base":"dash"},"darkly":{"media":{"uk":"media/uk/darkly__gb_1.mp3","us":"media/us/darkly__us_1.mp3"},"oxford":{"phon":"ˈdɑːkli","pos":"adverb","senses":[{"en":"in a threatening or unpleasant way","cn":"威胁地；险恶地；负面地","ex":{"en":"He hinted darkly that all was not well.","cn":"他悲观地暗示并非一切都顺利。"}},{"en":"showing a dark colour","cn":"漆黑地；乌黑地","ex":{"en":"Her eyes burned darkly.","cn":"她的眼里满是怒火。"}}]},"examples":[{"en":"He hinted darkly that all was not well.","cn":"他悲观地暗示并非一切都顺利。"},{"en":"Her eyes burned darkly.","cn":"她的眼里满是怒火。"}]},"daughters":{"lemma":"daughter"},"darker":{"lemma":"dark"},"dangled":{"oxford":{"phon":"ˈdæŋɡl","pos":"verb","senses":[{"en":"to hang or swing freely","cn":"悬垂；悬挂；悬荡；悬摆"},{"en":"to hold sth so that it hangs or swings freely","cn":"提着（某物，任其自然下垂或摆动）；来回摆动着"}]}},"dangers":{"lemma":"danger"},"days":{"lemma":"day"},"dates":{"lemma":"date"},"dating":{"oxford":{"phon":"ˈdeɪtɪŋ","pos":"noun","senses":[{"en":"the activity of having a romantic relationship with somebody, or meeting people who you might in future have a romantic relationship with","cn":"约会","ex":{"en":"For divorced people it can be a shock to go back on the dating scene.","cn":"对于离婚的人来说，重新回到约会现场可能会感到震惊。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(机构、服务等）介绍约会的，婚介的","en":"Dating agencies or services are for people who are trying to find a girlfriend or boyfriend.","ex":{"en":"I joined a dating agency.","cn":"我加入了一个婚介机构。"}}]},"base":"date"},"databases":{"lemma":"database"},"dances":{"lemma":"dance"},"dare":{"collins":{"senses":[{"pos":"VERB 动词","cn":"敢;有足够的胆量","en":"If you do not dare to do something, you do not have enough courage to do it, or you do not want to do it because you fear the consequences. If you dare to do something, you do something which requires a lot of courage.","ex":{"en":"Since he was stuck in a lift a year ago he hasn't dared to get back into one","cn":"自从一年前被困在电梯里之后，他就再也没敢乘过电梯。"}},{"pos":"VERB 动词","cn":"向…挑战;激…（做）；问…有没有胆量（做）","en":"If you dare someone to do something, you challenge them to prove that they are not frightened of doing it.","ex":{"en":"Over coffee, she lit a cigarette, her eyes daring him to comment","cn":"喝咖啡时，她点燃了一支烟，用挑衅的眼神看着他，谅他也不敢吭声。"}},{"pos":"N-COUNT 可数名词","cn":"挑战;激将","en":"A dare is a challenge which one person gives to another to do something dangerous or frightening.","ex":{"en":"He'd do pretty much anything on a dare","cn":"别人一激他，他就几乎什么事都做得出来。"}},{"pos":"PHRASE 短语","cn":"(用于警告)不准，你敢","en":"If you say to someone 'don't you dare' do something, you are telling them not to do it and letting them know that you are angry.","ex":{"en":"Don't speak to me like that. Don't you dare","cn":"不要那样跟我讲话。我不允许！"}},{"pos":"PHRASE 短语","cn":"（表示震惊和愤怒) 你竟敢，你怎么敢","en":"You say 'how dare you'' when you are very shocked and angry about something that someone has done.","ex":{"en":"How dare you pick up the phone and listen in on my conversations!","cn":"你竟敢拿起电话偷听我的谈话！"}},{"pos":"PHRASE 短语","cn":"恕我冒昧;恕我直言","en":"You use 'dare I say it' when you know that what you are going to say will disappoint or annoy someone.","ex":{"en":"Politicians usually attract younger women, dare I say it, because of the status they have in society.","cn":"恕我直言，由于政客的社会地位，他们通常容易吸引一些年轻的女性。"}},{"pos":"PHRASE 短语","cn":"(我想）可能，大概;想必","en":"You can use 'I dare say' or 'I daresay' before or after a statement to indicate that you believe it is probably true.","ex":{"en":"I dare say that the computer would provide a clear answer to that","cn":"想必计算机能就其给出一个清楚的答案。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be brave enough to do something that is dangerous or that you are afraid of doing -- used in questions, negatives, and sentences beginning with 'if'","cn":""},{"en":"to be brave enough to do something unpleasant or difficult that other people are afraid to do","cn":""},{"en":"to be calm and confident enough to do something that is frightening or dangerous","cn":""}]},"collocations":{"phrases":["ADV. hardly, scarcely I hardly dared breathe.","VERB + DARE wouldn't I wouldn't dare go by myself."]},"media":{"uk":"media/ldoce/hwd/bre/2/ld44dare.mp3","us":"media/ldoce/hwd/ame/3/dare1.mp3"},"examples":[{"en":"Some of the older boys had dared him to do it.","cn":"几个大男孩激他，问他敢不敢干这事。"},{"en":"‘I'll tell her about it.’ ‘Don't you dare!’ “","cn":"我要把这事告诉她。” “你敢！”"}],"oxford":{"phon":"deə(r)","pos":"verb","senses":[{"en":"to be brave enough to do something","cn":"敢于；胆敢","lab":"literary","ex":{"en":"She said it as loudly as she dared.","cn":"她壮着胆子大声说了出来。"}},{"en":"to persuade somebody to do something dangerous, difficult or embarrassing so that they can show that they are not afraid","cn":"激（某人做某事）；问（某人）有没有胆量（做某事）","g":"[transitive]","ex":{"en":"Go on! Take it! I dare you.","cn":"来呀！接受吧！我谅你也不敢。"}},{"en":"something dangerous, difficult or embarrassing that you try to persuade somebody to do, to see if they will do it","cn":"激将；挑战","lab":"British English","ex":{"en":"He climbed onto the roof for a dare.","cn":"他受到激将才爬上房顶。"},"pos":"noun"}]}},"daylight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日光","en":"Daylight is the natural light that there is during the day, before it gets dark.","ex":{"en":"It was still daylight but all the cars had their headlights on","cn":"还是大白天，但所有汽车的前灯都亮起来了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"天明","en":"Daylight is the time of day when it begins to get light.","ex":{"en":"Quinn returned shortly after daylight yesterday morning.","cn":"昨天早上天刚亮奎因就回来了。"}},{"pos":"PHRASE 短语","cn":"在光天化日之下;在大白天","en":"If you say that a crime is committed in broad daylight, you are expressing your surprise that it is done during the day when people can see it, rather than at night.","ex":{"en":"A girl was attacked on a train in broad daylight","cn":"光天化日之下，一个女孩在火车上遭到了袭击。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you can't afford something, you do not have enough money to buy it or pay for it","cn":""},{"en":"prices, charges, rents etc that are exorbitant or extortionate , are very much higher than they should be, and you think they are unfair","cn":""},{"en":"you say something is a rip-off when you think someone is unfairly charging too much money for it","cn":""}]},"collocations":{"phrases":["ADJ. broad, full He was robbed in broad daylight. | natural I prefer to work in natural daylight.","VERB + DAYLIGHT let in The thin curtains let in the daylight. | shut out The shutters were closed to keep out the daylight. | emerge into Th","DAYLIGHT + VERB filter through sth, flood in, penetrate sth A little daylight was filtering through the curtains. He drew back the curtains ","DAYLIGHT + NOUN hours The public has access during daylight hours.","PREP. before ~ She was up before daylight. | by ~ By daylight the fire was almost under control. | in ~ I can see better in daylight. | into","PHRASES the hours of daylight The machines roar incessantly during the hours of daylight."]},"media":{"uk":"media/ldoce/hwd/bre/d/daylight0205.mp3","us":"media/ldoce/hwd/ame/0/daylight.mp3"},"examples":[{"en":"You wouldn't believe some of the prices they charge; it's daylight robbery.","cn":"他们的要价有一些你都不会相信，简直就是在光天化日之下抢劫呀！"},{"en":"They emerged from the church into the bright daylight.","cn":"他们走出教堂来到明亮的日光下。"}],"oxford":{"phon":"ˈdeɪlaɪt","pos":"noun","senses":[{"en":"the light that comes from the sun during the day","cn":"日光","ex":{"en":"They emerged from the church into the bright daylight.","cn":"他们走出教堂来到明亮的日光下。"}}]}},"dam":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"坝;堤","en":"A dam is a wall that is built across a river in order to stop the water flowing and to make a lake.","ex":{"en":"...plans to build a dam on the Danube River.","cn":"在多瑙河上建坝的计划"}},{"pos":"VERB 动词","cn":"在（河）上筑坝","en":"To dam a river means to build a dam across it.","ex":{"en":"...plans to dam the nearby Delaware River","cn":"在附近的特拉华河上筑坝的计划"}},{"pos":"N-COUNT 可数名词","cn":"雌亲;母畜","en":"In the breeding of farm animals, an animal's dam is its mother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special wall built across a river or stream to stop the water from flowing, especially in order to make a lake or produce electricity","cn":"水坝﹐水堤﹐堤坝"},{"en":"the mother of a four-legged animal, especially a horse","cn":"母兽，〔尤指〕母马"},{"en":"to stop the water in a river or stream from flowing by building a special wall across it","cn":"筑坝拦〔水〕﹐在…中筑堤"}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"A barrier built to block the flow of water is called a dam . If you walk along a stream, you can see where beavers have built a dam out of mud and logs."}]},"collocations":{"phrases":["ADJ. hydroelectric","VERB + DAM build, construct | breach The dam has been breached and there is a danger of flooding.","DAM + VERB burst The dam burst and the valley was flooded. | hold sth back The dam holds back the water.","PREP. ~ across/on a large hydroelectric dam on the River Danube"]},"media":{"uk":"media/ldoce/hwd/bre/2/dam_v0205.mp3","us":"media/ldoce/hwd/ame/4/dam1.mp3"},"examples":[{"en":"Once she allowed her anger to show, it could not be dammed up again.","cn":"她一旦发起脾气来就不可收拾。"}],"oxford":{"phon":"dæm","pos":"noun","senses":[{"en":"a barrier that is built across a river in order to stop the water from flowing, used especially to make a reservoir (= a lake for storing water) or to produce electricity","cn":"水坝；拦河坝","ex":{"en":"the Narmada dam in India","cn":"印度讷尔默达大坝"}},{"en":"an artificial lake where rain or spring water is collected and stored","cn":"人工湖；水库","lab":"South African English","ex":{"en":"The dam was full of water.","cn":"水库里蓄满了水。"}},{"en":"the mother of some animals, especially horses","cn":"母兽；（尤指）母马，骒马","lab":"specialist"},{"en":"a small rubber sheet used by dentists to keep a tooth separate from the other teeth","cn":"橡皮障（牙医用的牙齿阻隔膜）"},{"en":"a small rubber sheet used to protect the mouth during sex","cn":"（性交时用的）口腔保护膜；口交保险膜"},{"en":"to build a dam across a river, especially in order to make an artificial lake for use as a water supply, etc.","cn":"（在河上）筑坝","ex":{"en":"plans to dam Colorado’s South Platte River","cn":"计划在科罗拉多州南普拉特河筑坝"},"pos":"verb"}]}},"daft":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚蠢的;不切实际的;古里古怪的","en":"If you describe a person or their behaviour as daft, you think that they are stupid, impractical, or rather strange.","ex":{"en":"He's not so daft as to listen to rumours","cn":"他不会蠢到去听信谣言的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing a total lack of good sense or good judgment. Stupid sounds very strong and is often used when you are annoyed or strongly criticizing someone’s behaviour","cn":""},{"en":"doing or saying things that are not sensible or serious, and that may make you feel embarrassed later. Silly sounds much gentler than stupid","cn":""},{"en":"not sensible, often in a way that is also amusing","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Daft means \"foolish, wacky, or nutty.\" like your daft idea of wearing flip-flops to hike through the snow so that you didn't ruin your boots."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | act, talk (both informal) Don't talk daft!","ADV. bloody (taboo) , really | completely, plain The decision is just plain daft. | a bit, pretty, rather"]},"media":{"uk":"media/ldoce/hwd/bre/0/daft0205.mp3","us":"media/ldoce/hwd/ame/1/daft.mp3"},"examples":[{"en":"She's not as daft as she looks.","cn":"她并不像看上去那么傻。"},{"en":"What a daft thing to say!","cn":"这样说真是太愚蠢了！"}],"oxford":{"phon":"dɑːft","pos":"adjective","senses":[{"en":"silly, often in a way that is funny","cn":"笨的；傻的；愚蠢可笑的","ex":{"en":"Don't be so daft!","cn":"别那么犯傻了！"}}]}},"dagger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"匕首;短剑","en":"A dagger is a weapon like a knife with two sharp edges."},{"pos":"PHRASE 短语","cn":"剑拔弩张;势不两立","en":"If you say that two people are at daggers drawn, you mean they are having an argument and are still very angry with each other.","ex":{"en":"She and her mother were at daggers drawn.","cn":"她和她母亲之间的关系异常紧张。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short pointed knife used as a weapon","cn":"匕首﹐短剑"},{"en":"to look at someone angrily","cn":"对某人怒目而视"},{"en":"if two people are at daggers drawn, they are extremely angry with each other","cn":"势不两立﹐剑拔弩张"}]},"collocations":{"phrases":["ADJ. curved | ceremonial, jewelled, ornamental","VERB + DAGGER draw | sheathe"]},"media":{"img":["media/ldoce/img/dagger.jpg","media/thumb/dagger.jpg"],"uk":"media/ldoce/hwd/bre/4/dagger0205.mp3","us":"media/ldoce/hwd/ame/d/dagger.mp3"},"oxford":{"phon":"ˈdæɡə(r)","pos":"noun","senses":[{"en":"a short pointed knife that is used as a weapon","cn":"匕首；短剑","ex":{"en":"Each man was armed with both sword and dagger.","cn":"每个人都配备了剑和匕首。"}}]}},"david":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a statue of a young man made by the artist michelangelo , which can be seen in Florence, in Italy. It is considered to be one of the best examples of the human form in art.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000003929.mp3","us":"media/ldoce/hwd/ame/6/p028-000003929.mp3"},"oxford":{"phon":"ˈdeɪvɪd","pos":"","senses":[{"en":"a first name for boys","cn":"戴维（男子名）"}]}},"dash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"飞奔;猛冲","en":"If you dash somewhere, you run or go there quickly and suddenly.","ex":{"en":"Suddenly she dashed down to the cellar","cn":"她突然冲下地窖。"}},{"pos":"VERB 动词","cn":"马上离开;赶紧走","en":"If you say that you have to dash, you mean that you are in a hurry and have to leave immediately.","ex":{"en":"Oh, Tim! I'm sorry but I have to dash","cn":"哦，蒂姆！很抱歉，我得马上走。"}},{"pos":"N-COUNT 可数名词","cn":"（往食物或饮料里添加的）少量，少许","en":"A dash of something is a small quantity of it which you add when you are preparing food or mixing a drink.","ex":{"en":"Add a dash of balsamic vinegar.","cn":"加入少许香脂醋。"}},{"pos":"N-COUNT 可数名词","cn":"（某种特质的）少量，些许","en":"A dash of a quality is a small amount of it that is found in something and often makes it more interesting or distinctive.","ex":{"en":"...a story with a dash of mystery thrown in.","cn":"带有些许神秘色彩的故事"}},{"pos":"VERB 动词","cn":"(朝墙上等)猛摔，猛掷，猛撞","en":"If you dash something against a wall or other surface, you throw or push it violently, often so hard that it breaks.","ex":{"en":"She seized the doll and dashed it against the stone wall with tremendous force.","cn":"她抓起玩具娃娃，用力往石墙上扔去。"}},{"pos":"VERB 动词","cn":"使（希望或期望）破灭","en":"If an event or person dashes someone's hopes or expectations, it destroys them by making it impossible that the thing that is hoped for or expected will ever happen.","ex":{"en":"The announcement dashed hopes of an early end to the crisis","cn":"这一宣告使得人们期盼危机早日结束的希望落了空。"}},{"pos":"N-SING 单数名词","cn":"急匆匆;仓促","en":"If you do something in a dash, you do it very quickly, perhaps with very bad results.","ex":{"en":"He's in a dash to get Russia back into Europe.","cn":"他急于让俄罗斯回归欧洲。"}},{"pos":"N-COUNT 可数名词","cn":"短跑（比赛）","en":"A dash is a short fast race."},{"pos":"N-COUNT 可数名词","cn":"破折号","en":"A dash is a straight, horizontal line used in writing, for example to separate two main clauses whose meanings are closely connected."},{"pos":"EXCLAM 感叹语","cn":"该死;可恶;讨厌","en":"You can say dash or dash it or dash it all when you are rather annoyed about something.","ex":{"en":"Dash it all. It's just not playing the game, is it?","cn":"可恶，那完全是不讲道义，是不是？"}},{"pos":"N-COUNT 可数名词","cn":"(汽车的)仪表板","en":"The dash of a car is its dashboard ."},{"pos":"N-UNCOUNT不可数名词","cn":"潇洒;闯劲;勇猛","en":"Dash is a mixture of stylishness, enthusiasm, and courage.","ex":{"en":"The Prince was driving with great fire and dash.","cn":"王子潇洒威猛地驱车而行。"}},{"pos":"PHRASE 短语","cn":"风度翩翩;大胆出位","en":"If you say that someone cuts a dash, you mean that they have an attractively stylish appearance or a rather bold manner.","ex":{"en":"If you're determined to cut a dash in a designer dress, consider hiring one.","cn":"如果你决意要身着设计师之作惊艳出位，那就考虑雇请一位时装设计师吧。"}},{"pos":"PHRASE 短语","cn":"（为逃离等而)飞速奔向，猛冲向","en":"If you make a dash for a place, you run there very quickly, for example to escape from someone or something.","ex":{"en":"I made a dash for the front door but he got there before me","cn":"我向前门奔去，但他抢在了我的前面。"}},{"pos":"PHRASAL VERB 短语动词","cn":"迅速前往","en":"If you dash off to a place, you go there very quickly.","ex":{"en":"He dashed off to lunch at the Hard Rock Cafe","cn":"他急匆匆前往硬石小馆去吃午餐。"}},{"pos":"PHRASAL VERB 短语动词","cn":"急速写好;匆匆写成","en":"If you dash off a piece of writing, you write or compose it very quickly, without thinking about it very much.","ex":{"en":"He dashed off a couple of novels.","cn":"他匆匆赶写出了几篇小说。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go somewhere or do something more quickly than usual, for example because you are late or you must finish something soon","cn":""},{"en":"to go somewhere very quickly, or to do something too quickly and without thinking carefully enough","cn":""},{"en":"to go somewhere very quickly, especially because there is something important or urgent you must do","cn":""}]},"collocations":{"phrases":["ADJ. quick, sudden | frantic, headlong, mad | final, last-minute","VERB + DASH make","PREP. ~ across We had to make a frantic dash across town to get our plane | ~ for He made a sudden dash for the door. | ~ from, ~ through Th","VERB + DASH add Add a dash of lemon juice.","PREP. ~ of The food is European with a dash of Morocco."]},"media":{"uk":"media/ldoce/hwd/bre/2/dash_v0205.mp3","us":"media/ldoce/hwd/ame/9/dash1.mp3"},"examples":[{"en":"When the doors opened, there was a mad dash for seats.","cn":"门一开，人们便疯狂地朝座位奔去。"},{"en":"He jumped off the bus and made a dash for the nearest bar.","cn":"他跳下公共汽车直奔近处的酒吧。"}],"oxford":{"phon":"dæʃ","pos":"noun","senses":[{"en":"an act of going somewhere suddenly and/or quickly","cn":"猛冲；突进；急奔","g":"[singular]","sc":"something done quickly","ex":{"en":"When the doors opened, there was a mad dash for seats.","cn":"门一开，人们便疯狂地朝座位奔去。"}},{"en":"an act of doing something quickly because you do not have enough time","cn":"匆忙；匆促；仓促","g":"[singular]","sc":"something done quickly","ex":{"en":"a last-minute dash to buy presents","cn":"利用最后一点时间匆忙买礼物"}},{"en":"a small amount of something that is added to something else","cn":"少量，少许（添加物）","g":"[countable, usually singular]","sc":"small amount","ex":{"en":"Add a dash of lemon juice.","cn":"加少量柠檬汁。"}},{"en":"the mark (—) used to separate parts of a sentence, often instead of a colon or in pairs instead of brackets","cn":"破折号","g":"[countable]","sc":"symbol"},{"en":"the longer of the two signals that are used in Morse code","cn":"（摩斯密码）划","g":"[countable]","sc":"symbol","ex":{"en":"It is broadcast in Morse code, the series of dots and dashes historically used to transmit information.","cn":"它以摩尔斯电码广播，摩尔斯电码是历史上用于传输信息的一系列点和划线。"}},{"en":"a race in which the people taking part run very fast over a short distance","cn":"短跑","g":"[countable, usually singular]","lab":"especially North American English","sc":"race","ex":{"en":"the 100-meter dash","cn":"百米赛跑"}},{"en":"a way of behaving that combines style, enthusiasm and confidence","cn":"气魄；活力；冲劲；锐气","g":"[uncountable]","lab":"old-fashioned, approving，，","sc":"way of behaving","ex":{"en":"He brought youthful energy, dash and charisma to the department.","cn":"他给部门带来了青春活力、冲劲和魅力。"}},{"en":"a dashboard (= the part of a car in front of the driver that has instruments and controls in it)","cn":"（汽车上的）仪表板","g":"[countable]","lab":"especially North American English, informal，，","sc":"part of car"},{"en":"to go somewhere very quickly","cn":"急奔；猛冲；疾行","g":"[intransitive]","sc":"go quickly","ex":{"en":"I must dash (= leave quickly), I'm late.","cn":"我得赶紧走，来不及了。"},"pos":"verb"},{"en":"to throw something, push somebody or make something fall violently onto a hard surface; to beat against a surface","cn":"猛掷；猛推；猛击；猛撞","g":"[transitive, intransitive]","sc":"throw/beat","ex":{"en":"The boat was dashed repeatedly against the rocks.","cn":"小船一次又一次撞在岩石上。"},"pos":"verb"}]}},"damaged":{"lemma":"damage","media":{"uk":"media/ldoce/hwd/bre/0/ld5_damaged.mp3","us":"media/ldoce/hwd/ame/0/ld5_damaged.mp3"}}});
